lsp4_is "$LSP4" '(vla-get-layer o2)' 1 '"Doors"' "LSP4_put: read back"
lsp4_is "$LSP4" '(vlax-put-property o2 "Color" 1)' 1 "nil" "LSP4_put: Color 1"
lsp4_is "$LSP4" '(cdr (assoc 62 (entget 2)))' 1 "1" "LSP4_put: entget group 62"
lsp4_is "$LSP4" '(vlax-get-property o2 "Color")' 1 "1" "LSP4_put: property"
