lsp4_is "$LSP4" '(vlax-get-property o5 "Area")' 2 "12.0" "LSP4_put: Area 4 x 3"
lsp4_is "$LSP4" '(vlax-put-property o5 "Closed" T)' 1 "nil" "LSP4_put: Closed T"
