lsp4_is "$LSP4" '(vlax-put-property o5 "Closed" nil)' 1 "nil" "LSP4_put: Closed nil opens it"
lsp4_is "$LSP4" '(vlax-get-property o5 "Closed")' 3 "nil" "LSP4_put: open"
lsp4_is "$LSP4" '(vlax-get-property o5 "Length")' 3 "11.0" "LSP4_put: the open path is 4 + 3 + 4"

# ---- refusals ----------------------------------------------------------------------------------------------------------------------------------------------
lsp4_err "$LSP4" '(vlax-put-property o1 "Length" 7.0)' 1 "property Length is read-only" "LSP4_put_neg: Length is read-only"
lsp4_err "$LSP4" '(vlax-put-property o2 "Area" 1.0)' 1 "property Area is read-only" "LSP4_put_neg: Area is read-only"
lsp4_err "$LSP4" '(vlax-put-property o1 "ObjectName" "x")' 1 "property ObjectName is read-only" "LSP4_put_neg: ObjectName"
lsp4_err "$LSP4" '(vlax-put-property o1 "Handle" "x")' 1 "property Handle is read-only" "LSP4_put_neg: Handle"
lsp4_err "$LSP4" "(vlax-put-property o3 \"StartPoint\" '(1 2 3))" 1 "property StartPoint is read-only" "LSP4_put_neg: an arc's StartPoint"
