lsp4_err "$LSP4" '(vlax-put-property o1 "Color" 1.5)' 1 "bad argument type: integerp for Color" "LSP4_put_neg: a real color"
lsp4_err "$LSP4" '(vlax-put-property o1 "Color" 0)' 1 "color 0 is not supported" "LSP4_put_neg: color 0"
