lsp4_err "$LSP4" '(vlax-put-property o2 "Radius" "big")' 1 "bad argument type: numberp" "LSP4_put_neg: a string radius"
lsp4_err "$LSP4" "(vlax-put-property o1 \"StartPoint\" '(1 2 3 4))" 1 "bad point in Put" "LSP4_put_neg: a four-coordinate point"
lsp4_err "$LSP4" '(vlax-put-property o1 "StartPoint" 5)' 1 "bad point in Put" "LSP4_put_neg: a number as a point"
