lsp4_err "$LSP4" "(vlax-put-property o6 \"Center\" '(1 2 3))" 1 "cannot be changed (only Layer and Color)" "LSP4_put_neg: an ellipse's centre"
lsp4_err "$LSP4" '(vlax-put-property o1 "Radius" 2.0)' 1 "has no property Radius" "LSP4_put_neg: a line has no Radius"
lsp4_err "$LSP4" '(vlax-get-property o1 "Radius")' 1 "has no property Radius" "LSP4_get_neg: a line has no Radius"
lsp4_err "$LSP4" '(vlax-get-property o1 "NoSuchProperty")' 1 "has no property NoSuchProperty" "LSP4_get_neg: no such property"
lsp4_err "$LSP4" '(vlax-get-property o4 "Length")' 1 "has no property Length" "LSP4_get_neg: a point has no Length"
lsp4_err "$LSP4" '(vlax-get-property 5 "Layer")' 1 "bad argument type: VLA-OBJECT in vlax-get-property" "LSP4_get_neg: a number is not an object"
lsp4_err "$LSP4" '(vlax-get-property o1 5)' 1 "bad argument type: stringp" "LSP4_get_neg: a number as the property name"
lsp4_err "$LSP4" '(vlax-get-property o1)' 1 "too few arguments to vlax-get-property" "LSP4_get_neg: no property"
lsp4_err "$LSP4" '(vlax-put-property o1 "Layer")' 1 "too few arguments to vlax-put-property" "LSP4_put_neg: no value"
lsp4_err "$LSP4" '(vla-get-radius o1)' 1 "has no property radius" "LSP4_get_neg: vla-get-radius on a line"
lsp4_err "$LSP4" '(vla-get-layer 5)' 1 "bad argument type: VLA-OBJECT in VLA-GET-LAYER" "LSP4_get_neg: vla-get-layer of a number"
lsp4_err "$LSP4" '(vla-get-layer)' 1 "bad argument type: VLA-OBJECT in VLA-GET-LAYER" "LSP4_get_neg: vla-get-layer of nothing"
